/* v28.xx (cw-uc-racksquiet) b-31 step 7, critic on 14 (P0 "every action has a 1-3 line explaining paragraph"): the array and data core explainer lines are hidden; the rack cost line stays (it is information) and so does his import line. */
#root #mfarrayhint, #root #mfslothint{ display:none !important; }

check:
{v:'VER',what:'the racks tab hides the array and data core explainer lines',
 run:function(){
   var bad=[];
   try{
     ['mfarrayhint','mfslothint'].forEach(function(id){
       var e=document.getElementById(id);
       if(!e) bad.push('no '+id); else if(getComputedStyle(e).display!=='none') bad.push(id+' displays'); });
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   return bad.length?bad.join('; '):null; }},
